import { AltArrowDownIcon as ChevronDownIcon } from '@solar-icons/react/linear/alt-arrow-down'
import { FolderIcon } from '@solar-icons/react/linear/folder'
import { DocumentIcon as FileIcon } from '@solar-icons/react/linear/document'
import * as React from 'react'

import { Button } from '@/components/ui/button'
import { cn } from 'cn'

interface CommitFile {
  path: string
  additions: number
  deletions: number
}

interface CommitProps extends React.ComponentProps<'article'> {
  files: CommitFile[]
  onOpen?: () => void
}

function ChangeCounts({ additions, deletions }: { additions: number; deletions: number }) {
  return (
    <span className="ml-auto flex shrink-0 gap-4 font-mono text-xs tabular-nums">
      <span
        className="text-emerald-600 dark:text-emerald-400"
        aria-label={`${additions} additions`}
      >
        +{additions}
      </span>
      <span className="text-red-600 dark:text-red-400" aria-label={`${deletions} deletions`}>
        −{deletions}
      </span>
    </span>
  )
}

function CommitFileRow({ file, nested = false }: { file: CommitFile; nested?: boolean }) {
  const name = file.path.split('/').pop() ?? file.path
  const isReact = /\.[jt]sx$/.test(name)
  const isMarkdown = /\.mdx?$/.test(name)
  const Icon = isReact ? ReactIcon : isMarkdown ? MarkdownIcon : FileIcon

  return (
    <li className={cn('flex min-h-8 items-center gap-2.5 px-4', nested ? 'pl-12' : 'pl-9')}>
      <Icon
        aria-hidden="true"
        className={cn(
          'size-4 shrink-0',
          isReact && 'text-sky-500 dark:text-sky-400',
          isMarkdown && 'text-green-600 dark:text-green-400',
        )}
      />
      <span className="min-w-0 truncate font-mono text-sm text-foreground/85" title={file.path}>
        {name}
      </span>
      <ChangeCounts additions={file.additions} deletions={file.deletions} />
    </li>
  )
}

function Commit({ className, files, onOpen, ...props }: CommitProps) {
  const [expanded, setExpanded] = React.useState(true)
  const [collapsedFolders, setCollapsedFolders] = React.useState<Set<string>>(new Set())
  const contentId = React.useId()
  const groups = new Map<string, CommitFile[]>()
  for (const file of files) {
    const folder = file.path.includes('/') ? file.path.slice(0, file.path.lastIndexOf('/')) : ''
    const group = groups.get(folder) ?? []
    group.push(file)
    groups.set(folder, group)
  }
  const additions = files.reduce((total, file) => total + file.additions, 0)
  const deletions = files.reduce((total, file) => total + file.deletions, 0)

  function toggleFolder(folder: string) {
    setCollapsedFolders((current) => {
      const next = new Set(current)
      if (next.has(folder)) next.delete(folder)
      else next.add(folder)
      return next
    })
  }

  return (
    <article
      data-slot="commit"
      className={cn(
        'overflow-hidden rounded-[16px] bg-card font-sans text-sm font-[450] tracking-[-0.05px] text-muted-foreground shadow-card',
        className,
      )}
      {...props}
    >
      <header className="flex flex-wrap items-center gap-x-3 gap-y-2 bg-muted/25 px-4 py-3">
        <h3 className="card-heading text-foreground">
          {files.length} changed {files.length === 1 ? 'file' : 'files'}
        </h3>
        <span className="flex gap-1.5 text-sm tabular-nums">
          <span className="text-emerald-600 dark:text-emerald-400">+{additions}</span>
          <span className="text-red-600 dark:text-red-400">−{deletions}</span>
        </span>
        <div className="ml-auto flex items-center gap-2">
          <Button
            aria-label={expanded ? 'Collapse changed files' : 'Expand changed files'}
            aria-expanded={expanded}
            aria-controls={contentId}
            onClick={() => setExpanded(!expanded)}
            size="icon-sm"
            variant="ghost"
          >
            <ChevronDownIcon
              className={cn(
                'size-4 transition-[rotate] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none',
                !expanded && '-rotate-90',
              )}
            />
          </Button>
          <Button
            className="h-7 rounded-full px-2 text-sm font-[450] tracking-[-0.05px] text-muted-foreground hover:text-foreground"
            disabled={!onOpen}
            onClick={onOpen}
            size="sm"
            variant="ghost"
          >
            <FileIcon data-icon="inline-start" /> Open diff
          </Button>
        </div>
      </header>
      <div
        id={contentId}
        hidden={!expanded}
        className="py-2 transition-opacity duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] starting:opacity-0"
      >
        {files.length === 0 && <p className="px-4 py-2 text-xs leading-5">No changed files.</p>}
        {Array.from(groups, ([folder, groupFiles]) =>
          folder ? (
            <div key={folder}>
              <button
                type="button"
                aria-expanded={!collapsedFolders.has(folder)}
                onClick={() => toggleFolder(folder)}
                className="flex min-h-8 w-full items-center gap-2.5 px-4 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
              >
                <ChevronDownIcon
                  aria-hidden="true"
                  className={cn(
                    'size-3.5 shrink-0 transition-[rotate] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none',
                    collapsedFolders.has(folder) && '-rotate-90',
                  )}
                />
                <FolderIcon aria-hidden="true" className="size-4 shrink-0" />
                <span className="min-w-0 truncate font-mono" title={folder}>
                  {folder}
                </span>
                <ChangeCounts
                  additions={groupFiles.reduce((total, file) => total + file.additions, 0)}
                  deletions={groupFiles.reduce((total, file) => total + file.deletions, 0)}
                />
              </button>
              {!collapsedFolders.has(folder) && (
                <ul className="transition-opacity duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] starting:opacity-0">
                  {groupFiles.map((file) => (
                    <CommitFileRow key={file.path} file={file} nested />
                  ))}
                </ul>
              )}
            </div>
          ) : (
            <ul key="root">
              {groupFiles.map((file) => (
                <CommitFileRow key={file.path} file={file} />
              ))}
            </ul>
          ),
        )}
      </div>
    </article>
  )
}

export { Commit }
export type { CommitFile, CommitProps }

